use std::sync::{Arc};
use std::thread;

fn main() {
  let counter = Arc::new(0);
  let mut handles = vec![];
  for _ in 0..10 {
    let counter_clone = Arc::clone(&counter);
    let handle = thread::spawn(move || {
      let mut num =
      counter_clone.lock().unwrap();
      *num += 1;
    });
    handles.push(handle);
  }
  for handle in handles {
    handle.join().unwrap();
  }
  println!(“Resultado final do contador: {}”,
  *counter.lock().unwrap());
}
```

